diff --git a/src/ui/glyph_cache.c b/src/ui/glyph_cache.c
index 589987f..0e5eaa9 100644
--- a/src/ui/glyph_cache.c
+++ b/src/ui/glyph_cache.c
@@ -12,6 +12,8 @@
 #include "stb_truetype.h"

 #define GLYPH_PADDING 1
+// The largest glyph a page has room for next to its white square.
+#define GLYPH_SIZE_MAX (VD_GLYPH_ATLAS_PAGE_SIZE - VD_GLYPH_ATLAS_WHITE_SIZE - GLYPH_PADDING)

 #define ZWJ 0x200d
 #define VS15 0xfe0e
@@ -204,12 +206,23 @@ static bool page_place(AtlasPage *page, int width, int height, int *x, int *y)
     return true;
 }

+// Paints the white square into empty pixels; glyphs start after it.
+static void start_page(AtlasPage *page)
+{
+    for (int row = 0; row < VD_GLYPH_ATLAS_WHITE_SIZE; row++) {
+        memset(page->pixels + (size_t)row * VD_GLYPH_ATLAS_PAGE_SIZE * 4, 255, VD_GLYPH_ATLAS_WHITE_SIZE * 4);
+    }
+    page->dirty = true;
+    page->cursor_x = VD_GLYPH_ATLAS_WHITE_SIZE + GLYPH_PADDING;
+    page->cursor_y = 0;
+    page->row_height = VD_GLYPH_ATLAS_WHITE_SIZE;
+}
+
 static void clear_page(int index)
 {
     AtlasPage *page = &g_pages[index];
     memset(page->pixels, 0, VD_GLYPH_ATLAS_PAGE_BYTES);
-    page->dirty = true;
-    page->cursor_x = page->cursor_y = page->row_height = 0;
+    start_page(page);
     // hmdel moves the last entry into the deleted slot, which a backwards walk has already visited.
     for (ptrdiff_t i = hmlen(g_glyphs) - 1; i >= 0; i--) {
         if (g_glyphs[i].value.page != index) continue;
@@ -226,7 +239,7 @@ static void clear_page(int index)
 // The page that now holds a width x height rect at (x, y), or -1 when no page can take it this frame.
 static int atlas_allocate(int width, int height, int *x, int *y)
 {
-    if (width > VD_GLYPH_ATLAS_PAGE_SIZE || height > VD_GLYPH_ATLAS_PAGE_SIZE) return -1;
+    if (width > GLYPH_SIZE_MAX || height > GLYPH_SIZE_MAX) return -1;
     if (g_current_page >= 0 && page_place(&g_pages[g_current_page], width, height, x, y)) return g_current_page;

     int index;
@@ -235,6 +248,7 @@ static int atlas_allocate(int width, int height, int *x, int *y)
         if (!pixels) return -1;
         index = g_page_count++;
         g_pages[index] = (AtlasPage){.pixels = pixels};
+        start_page(&g_pages[index]);
     } else {
         index = 0;
         for (int i = 1; i < g_page_count; i++) {
@@ -412,7 +426,7 @@ static bool find_emoji(const VdGlyphFont *font, int size, const VdEmojiSequence
             continue;
         }
         bool placed = true;
-        if (size > VD_GLYPH_ATLAS_PAGE_SIZE) {
+        if (size > GLYPH_SIZE_MAX) {
             // It keeps its advance and draws nothing, rather than loading again every frame.
             *glyph = (VdGlyph){.page = -1, .advance = (float)size, .color = true};
         } else {

diff --git a/src/ui/text.c b/src/ui/text.c
index 2bb5a38..13d9686 100644
--- a/src/ui/text.c
+++ b/src/ui/text.c
@@ -11,6 +11,8 @@

 static Texture2D g_page_textures[VD_GLYPH_ATLAS_PAGE_MAX];
 static bool g_overflow_warned = false;
+static Texture2D g_raylib_shapes_texture;
+static Rectangle g_raylib_shapes_source;

 void text_begin_frame(void)
 {
@@ -19,6 +21,7 @@ void text_begin_frame(void)

 void text_reset(void)
 {
+    if (IsTextureValid(g_page_textures[0])) SetShapesTexture(g_raylib_shapes_texture, g_raylib_shapes_source);
     for (int i = 0; i < VD_GLYPH_ATLAS_PAGE_MAX; i++) {
         if (IsTextureValid(g_page_textures[i])) UnloadTexture(g_page_textures[i]);
     }
@@ -45,6 +48,14 @@ void text_upload_pages(void)
         Image image = {(void *)pixels, VD_GLYPH_ATLAS_PAGE_SIZE, VD_GLYPH_ATLAS_PAGE_SIZE, 1,
                        PIXELFORMAT_UNCOMPRESSED_R8G8B8A8};
         g_page_textures[page] = LoadTextureFromImage(image);
+        if (page == 0 && IsTextureValid(g_page_textures[0])) {
+            // Shapes draw from page 0's white square, so they batch with the text around them: a texture switch
+            // costs a draw call, and a screen of Buttons alternates shapes and text.
+            g_raylib_shapes_texture = GetShapesTexture();
+            g_raylib_shapes_source = GetShapesTextureRectangle();
+            SetShapesTexture(g_page_textures[0],
+                             (Rectangle){1, 1, VD_GLYPH_ATLAS_WHITE_SIZE - 2, VD_GLYPH_ATLAS_WHITE_SIZE - 2});
+        }
         TraceLog(LOG_DEBUG, "TEXT: Glyph atlas page %d of %d added (%d KiB)", page + 1, VD_GLYPH_ATLAS_PAGE_MAX,
                  VD_GLYPH_ATLAS_PAGE_BYTES / 1024);
     }

diff --git a/tests/glyph_cache_harness.c b/tests/glyph_cache_harness.c
index e55a966..358c19f 100644
--- a/tests/glyph_cache_harness.c
+++ b/tests/glyph_cache_harness.c
@@ -45,6 +45,17 @@ static bool same_shape(VdGlyph a, VdGlyph b)
            a.advance == b.advance;
 }

+static bool has_white_square(const unsigned char *pixels)
+{
+    for (int row = 0; pixels && row < VD_GLYPH_ATLAS_WHITE_SIZE; row++) {
+        for (int col = 0; col < VD_GLYPH_ATLAS_WHITE_SIZE; col++) {
+            const unsigned char *pixel = pixels + ((size_t)row * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)col) * 4;
+            if (pixel[0] != 255 || pixel[1] != 255 || pixel[2] != 255 || pixel[3] != 255) return false;
+        }
+    }
+    return pixels != NULL;
+}
+
 static void test_utf8(void)
 {
     expect_utf8("A", 'A', 1, "ASCII decodes as itself");
@@ -97,6 +108,8 @@ static void test_hits_and_sizes(const VdGlyphFont *font)
         }
     }
     expect(covered, "the glyph's rect holds coverage");
+    expect(has_white_square(pixels), "a page starts with an opaque white square for shapes");
+    expect(a.x > VD_GLYPH_ATLAS_WHITE_SIZE || a.y > VD_GLYPH_ATLAS_WHITE_SIZE, "glyphs leave the white square alone");

     VdGlyphFontMetrics metrics = glyph_font_metrics(font, 30);
     expect(fabsf(metrics.ascent + metrics.descent - 30.0f) < 0.01f, "ascent plus descent is the Font Size");
@@ -717,6 +730,7 @@ static void test_pages(const VdGlyphFont *full)
     glyph_cache_begin_frame();
     VdGlyph placed = glyph_cache_get(full, size, refused);
     expect(placed.page == 0, "a later frame clears the least recently used page");
+    expect(has_white_square(glyph_cache_take_dirty_page(0)), "a cleared page keeps its white square");
     expect(glyph_cache_stats().pages == VD_GLYPH_ATLAS_PAGE_MAX, "clearing a page keeps the cap");
     expect(glyph_cache_stats().glyphs < glyphs_before, "clearing a page drops its glyphs");
